using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class CathedralBellChecks {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){var state=new SliceState();Check(state.Valid(),"Legacy season rejected");state.Cathedral.bellRings=1;Check(!state.Valid(),"Unbuilt shrine rang bell");state.Cathedral.level=state.Cathedral.authorized=1;state.Cathedral.nextBellAt=90;Check(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(state)).Valid(),"Saved bell/cooldown invalid");state.Social(0).bellVisits=1;Check(!state.Valid(),"Uncompleted attendance accepted");state.Social(0).rituals=1;Check(state.Valid(),"Confirmed visit invalid");state.Cathedral.nextBellAt=float.NaN;Check(!state.Valid(),"Nonfinite bell cooldown accepted");Debug.Log("BWVR_CATHEDRAL_BELL_MODEL_PASS");}
 public static void VerifyRuntime(Action<VillageCathedral,string> capture=null){
  var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var field=typeof(QuestSlice).GetField("state",F);var original=(SliceState)field.GetValue(slice);var temple=slice.GetComponentInChildren<VillageCathedral>();var world=slice.GetComponentInChildren<VillageResources>();var god=slice.GetComponentInChildren<CreatureHybrid>();var worship=(VillageWorship)typeof(QuestSlice).GetField("worship",F).GetValue(slice);var input=(Func<bool>)typeof(VillageCathedral).GetField("bellInput",F).GetValue(temple);var jobs=world.Gatherers.Select(g=>g.GetComponent<VillagerRoutine>()).ToArray();var positions=jobs.Select(j=>j.transform.position).ToArray();var rotations=jobs.Select(j=>j.transform.rotation).ToArray();var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true};bool allowed=true;god.Interrupt("Cathedral bell QA");field.SetValue(slice,test);
  try{
   foreach(var j in jobs){j.GetComponent<VillagerSocial>().ResetTask();j.GetComponent<VillagerExploration>().ResetTask();j.GetComponent<VillagerBlockPlay>().ResetTask();j.GetComponent<VillagerResourceGathering>().Cancel();j.ResetTask();j.GetComponent<VillagerSocial>().Memory.faith=.31f;}
   world.ResetWorld();slice.GetComponentInChildren<VillageFamilies>().ResetWorld();temple.ResetWorld();worship.ResetWorld();temple.BindBell(worship,()=>allowed);Check(!temple.TryRingBell()&&test.Cathedral.bellRings==0,"Bell rang before completion");test.Cathedral.level=test.Cathedral.authorized=1;temple.Advance(.1f);Check(temple.BellTarget.gameObject.activeInHierarchy,"Built shrine has no gathering bell");capture?.Invoke(temple,"ready");
   allowed=false;Check(!temple.TryRingBell(),"Blocked input rang bell");allowed=true;test.paused=true;Check(!temple.TryRingBell(),"Pause rang bell");test.paused=false;
   var target=temple.BellTarget.GetComponent<BoxCollider>();Physics.SyncTransforms();var ray=new Ray(target.bounds.center+Vector3.up*.2f,Vector3.down);Check(Physics.Raycast(ray,out var hit,.4f,~0,QueryTriggerInteraction.Collide)&&hit.collider.GetComponentInParent<SpatialTarget>()==temple.BellTarget,"Pointer cannot reach bell");temple.BellTarget.Activate();Check(test.Cathedral.bellRings==1&&!temple.TryRingBell(),"Activation duplicated bell/window");capture?.Invoke(temple,"ring");
   var nav=world.Navigation;for(int i=0;i<jobs.Length;i++){var wanted=temple.Entrance+Vector3.back*nav.Scale*(25+i);Check(nav.Sample(wanted,jobs[i].GetComponent<IslandNavigator>().profile,5,out var at),"No bell audience stage");jobs[i].transform.position=nav.ProjectFoot(at,jobs[i].GetComponent<IslandNavigator>().profile);jobs[i].GetComponent<IslandNavigator>().ResetRoute();}
   jobs[0].BeginCathedral();Check(!worship.Tick(jobs[0],.1f)&&jobs[0].BuildingCathedral,"Bell stole builder");jobs[1].GetComponent<CarryItem>().held=true;Check(!worship.Tick(jobs[1],.1f),"Held villager joined");jobs[1].GetComponent<CarryItem>().held=false;jobs[2].GetComponent<VillagerSocial>().Memory.injury=.2f;Check(!worship.Tick(jobs[2],.1f),"Injured villager joined");
   for(int i=3;i<jobs.Length;i++)worship.Tick(jobs[i],.1f);Check(worship.BellParticipants>0&&worship.BellParticipants<=4,"No bounded voluntary audience");var active=jobs.Where(worship.Active).ToArray();Check(active.Length<=4,"Bell forced whole village");var destination=(Vector3[])typeof(VillageWorship).GetField("destinations",F).GetValue(worship);var visitor=active[0];int identity=Array.IndexOf(jobs,visitor);visitor.transform.position=destination[identity];visitor.GetComponent<IslandNavigator>().ResetRoute();
   test.paused=true;float seconds=visitor.GetComponent<VillagerSocial>().Memory.worshipSeconds;worship.Tick(visitor,.5f);Check(visitor.GetComponent<VillagerSocial>().Memory.worshipSeconds==seconds,"Paused visitor prayed");test.paused=false;for(int i=0;i<100&&worship.Active(visitor);i++){test.Hybrid.time+=.1f;worship.Tick(visitor,.1f);}Check(visitor.GetComponent<VillagerSocial>().Memory.bellVisits==1&&!worship.Active(visitor),"Completed gathering not remembered");Check(!worship.Tick(visitor,.1f)&&visitor.GetComponent<VillagerSocial>().Memory.bellVisits==1,"One invitation credited repeat visit");
   var interrupted=active.FirstOrDefault(j=>j!=visitor);if(interrupted!=null){interrupted.GetComponent<CarryItem>().held=true;worship.Tick(interrupted,.1f);Check(!worship.Active(interrupted)&&interrupted.GetComponent<VillagerSocial>().Memory.bellVisits==0,"Pickup credited an unfinished visit");interrupted.GetComponent<CarryItem>().held=false;}
   Check(test.relationships.All(m=>Mathf.Abs(m.faith-.31f)<.001f)&&test.Hybrid.Evidence.completedCreatureActions==0,"Bell fabricated faith or creature work");var bellPosition=temple.BellPosition;typeof(QuestSlice).GetMethod("Save",F).Invoke(slice,null);typeof(QuestSlice).GetMethod("Load",F).Invoke(slice,null);test=(SliceState)field.GetValue(slice);temple.ResetWorld();worship.ResetWorld();Check(test.Valid()&&test.Cathedral.bellRings==1&&test.Social(identity).bellVisits==1&&worship.Worshippers==0&&!temple.TryRingBell()&&temple.BellPosition==bellPosition,"Native resume lost visit/cooldown or replayed gathering");
   test.Hybrid.time=test.Cathedral.nextBellAt+1;Check(temple.TryRingBell()&&test.Cathedral.bellRings==2,"Bell failed to rearm after saved cooldown");test.Religion.fanatic=true;Check(!temple.TryRingBell(),"Fanatic gathering reinvited");Check(Resources.Load<AudioClip>("IslandAudio/bell").channels==1,"Missing mono bell sound");Debug.Log("BWVR_CATHEDRAL_BELL_RUNTIME_PASS: sourced target/raycast, input/pause/cooldown, voluntary four-person cap, busy/held/injured guards, completed vs interrupted visits, unchanged faith, native Save/Load and rearm");
  }finally{foreach(var j in jobs){j.GetComponent<CarryItem>().held=false;j.ResetTask();}field.SetValue(slice,original);temple.BindBell(worship,input);temple.ResetWorld();worship.ResetWorld();world.ResetWorld();slice.GetComponentInChildren<VillageFamilies>().ResetWorld();for(int i=0;i<jobs.Length;i++){jobs[i].transform.SetPositionAndRotation(positions[i],rotations[i]);jobs[i].GetComponent<IslandNavigator>().ResetRoute();}god.NewSeason();}
 }
}
}
